WITH kept_keys AS (SELECT id, account_type FROM accounts INTERSECT ALL SELECT id, account_type FROM accounts WHERE status IS NULL), reconciled AS (SELECT s.* FROM accounts s INNER JOIN kept_keys k ON s.id = k.id AND s.account_type = k.account_type) SELECT s.id, s.customer_id, s.opened_date, (SELECT SUM(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS sum_subscription_monthly_fee FROM reconciled s;
